{"hypotheses": [
  {
    "name": "Cash-Efficient Intangible Growth",
    "mechanism": "Firms with high intangible asset growth funded by internally generated cash flows avoid costly external financing and signal efficient investments likely to create sustainable value. Combining high GrLTNOA (intangible asset growth) with high CF (cash flow to market) and penalizing NetDebtFinance isolates these firms, generating returns not captured by components alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "GrLTNOA"},
        {"weight": 1.0, "primitive": "CF"},
        {"weight": -1.0, "primitive": "NetDebtFinance"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "GrLTNOA", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Defensive Alpha through Reduced Volatility and Cash Payouts",
    "mechanism": "Stocks with low realized volatility and high payout yields reflect defensive characteristics, offering downside protection and steady cash returns. Combining -RealizedVol with NetPayoutYield captures a defensive premium unavailable to either alone because it systematically avoids both high-risk and unrewarded low-yield firms.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "RealizedVol"},
        {"weight": 1.0, "primitive": "NetPayoutYield"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Quality Momentum with Analyst Confirmation",
    "mechanism": "High-profitability firms (OperProf) exhibiting strong intermediate momentum (IntMom) and receiving recent upward analyst revisions (AnalystRevision) are more likely to sustain outperformance, as external analysts validate quality-driven momentum. The triple signal reduces false positives found in each component alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 0.5, "primitive": "IntMom"},
        {"weight": 0.5, "primitive": "AnalystRevision"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.95,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Skeptical Growth: High Asset Growth, Low Analyst Optimism",
    "mechanism": "Firms with strong asset growth (AssetGrowth) but facing subdued analyst optimism (AOP) may be underappreciated by the market, especially if also exhibiting positive customer momentum (CustomerMomentum), suggesting growth overlooked by consensus and thus underpriced.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": -1.0, "primitive": "AOP"},
        {"weight": 0.5, "primitive": "CustomerMomentum"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AOP", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Intangible Capital Defensive Alpha",
    "mechanism": "Stocks with high brand investment (BrandInvest) and high organizational capital (OrgCap) but low market leverage (Leverage) combine resilient intangible assets with conservative balance sheets, producing defensiveness not replicated by any single input.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": -1.0, "primitive": "Leverage"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Contrarian Profitability Momentum",
    "mechanism": "Combining negative recent return momentum (STreversal) with high gross profitability (GP) and positive change in asset turnover (ChAssetTurnover) targets temporarily out-of-favor, operationally improving firms. This captures mean reversion in price, conditional on improving business quality.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "GP"},
        {"weight": 1.0, "primitive": "ChAssetTurnover"},
        {"weight": 1.0, "primitive": "STreversal"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Earnings Surprise-Backed Value",
    "mechanism": "Firms with low price-to-earnings (EP) and recent positive earnings surprises (EarningsSurprise), but low analyst forecast dispersion (ForecastDispersion), offer underpriced, high-quality opportunities where consensus is forming post-surprise. This mitigates risks of classic value traps.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "EP"},
        {"weight": 1.0, "primitive": "EarningsSurprise"},
        {"weight": -0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "correlation", "primitive": "EarningsSurprise", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Governance-Backed Momentum",
    "mechanism": "Stocks exhibiting strong 12-month momentum (Mom12m) and high governance scores (Governance), but low net equity financing (NetEquityFinance), are less likely to have their momentum interrupted by dilutive capital actions or governance failures, leading to more reliable trend persistence.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": 1.0, "primitive": "Governance"},
        {"weight": -1.0, "primitive": "NetEquityFinance"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 24
  }
]}
